window.SHIORI_DATA=window.SHIORI_DATA||{};SHIORI_DATA['n3_grammar']=[{"pattern":"〜うちに","meaning":"while ~ (before the situation changes)","formation":"Verb dictionary / ている / ない-form + うちに; い-adj + うちに; な-adj + なうちに; Noun + のうちに","note":"Do something while a state lasts. 〜ないうちに means 'before ~ happens'.","examples":[{"ja":"若いうちに色々な国へ行きたい。","en":"I want to visit many countries while I'm young."},{"ja":"暗くならないうちに帰りましょう。","en":"Let's go home before it gets dark."},{"ja":"{温|あたた}かいうちに食べてください。","en":"Please eat it while it's warm."}],"id":"n3g1"},{"pattern":"〜最中に","meaning":"right in the middle of ~","formation":"Verb ている + 最中(に / だ); Noun + の最中(に / だ)","note":"Usually followed by an unexpected interruption. 〜最中だ means 'is right in the middle of ~'.","examples":[{"ja":"会議の最中に電話が鳴った。","en":"The phone rang right in the middle of the meeting."},{"ja":"料理を作っている最中に、{停電|ていでん}になった。","en":"The power went out while I was in the middle of cooking."},{"ja":"今は試験の最中だから、静かにしてください。","en":"An exam is going on right now, so please be quiet."}],"id":"n3g2"},{"pattern":"〜たとたん(に)","meaning":"the moment ~; just as ~ (something unexpected happened)","formation":"Verb た-form + とたん(に)","note":"The second clause is a sudden, often surprising event, not the speaker's intention, request or plan.","examples":[{"ja":"窓を開けたとたん、強い風が入ってきた。","en":"The moment I opened the window, a strong wind blew in."},{"ja":"立ち上がったとたんに、頭が痛くなった。","en":"As soon as I stood up, I got a headache."},{"ja":"彼は家に着いたとたん、寝てしまった。","en":"He fell asleep the moment he got home."}],"id":"n3g3"},{"pattern":"〜たところ","meaning":"when I did ~ (I found that / the result was ~)","formation":"Verb た-form + ところ","note":"Describes an action and the result that followed; slightly formal. The result is past tense.","examples":[{"ja":"先生に相談したところ、親切に教えてくれた。","en":"When I consulted my teacher, she kindly explained it to me."},{"ja":"駅で聞いたところ、電車は遅れているということだった。","en":"When I asked at the station, I was told the train was delayed."},{"ja":"新しい薬を飲んだところ、すぐに熱が下がった。","en":"When I took the new medicine, my fever went down right away."}],"id":"n3g4"},{"pattern":"〜ところに / 〜ところへ","meaning":"just when ~ (someone came / something happened)","formation":"Verb dictionary / ている / た-form + ところに・ところへ","note":"Something happens at exactly that moment, often interrupting. ところへ is common with 来る and 帰る.","examples":[{"ja":"出かけようとしているところに、友達から電話がかかってきた。","en":"Just as I was about to go out, a friend called."},{"ja":"家族で食事をしているところへ、父が帰ってきた。","en":"My father came home just as the family was eating."},{"ja":"ちょうど君の話をしていたところに、君が来た。","en":"You showed up just when we were talking about you."}],"id":"n3g5"},{"pattern":"〜ところだった","meaning":"almost ~; nearly ~ (but it didn't happen)","formation":"Verb dictionary form + ところだった (often with もう少しで / 危うく)","note":"Expresses a narrow escape from something, usually something bad.","examples":[{"ja":"もう少しで車にひかれるところだった。","en":"I was almost hit by a car."},{"ja":"目覚まし時計がなかったら、遅刻するところだった。","en":"If it weren't for my alarm clock, I would have been late."},{"ja":"危うく大事な約束を忘れるところだった。","en":"I nearly forgot an important appointment."}],"id":"n3g6"},{"pattern":"〜際(に)","meaning":"when ~; on the occasion of ~ (formal)","formation":"Verb dictionary / た-form + 際(に); Noun + の際(に)","note":"Formal version of 〜とき, common in announcements, notices and business speech.","examples":[{"ja":"非常の際は、このドアから出てください。","en":"In an emergency, please exit through this door."},{"ja":"日本に来た際に、友人の家に{泊|と}まりました。","en":"When I came to Japan, I stayed at a friend's house."},{"ja":"部屋を出る際には、電気を消してください。","en":"Please turn off the lights when you leave the room."}],"id":"n3g7"},{"pattern":"〜たび(に)","meaning":"every time ~; whenever ~","formation":"Verb dictionary form + たび(に); Noun + のたび(に)","note":"The main clause describes something that happens each time without exception.","examples":[{"ja":"この歌を聞くたびに、子供のころを思い出す。","en":"Every time I hear this song, I remember my childhood."},{"ja":"{出張|しゅっちょう}のたびに、家族にお土産を買う。","en":"Every time I go on a business trip, I buy souvenirs for my family."},{"ja":"彼女は会うたびにきれいになっている。","en":"She gets prettier every time I see her."}],"id":"n3g8"},{"pattern":"〜て以来","meaning":"ever since ~","formation":"Verb て-form + 以来; Noun + 以来","note":"For a state continuing since a past event; not used for very recent events (use 〜てから).","examples":[{"ja":"日本に来て以来、一度も国に帰っていない。","en":"Since coming to Japan, I haven't gone back to my country even once."},{"ja":"{卒業|そつぎょう}して以来、彼とは会っていない。","en":"I haven't seen him since we graduated."},{"ja":"去年の夏以来、体重が五キロも増えた。","en":"Since last summer, I've gained as much as five kilograms."}],"id":"n3g9"},{"pattern":"〜てからでないと","meaning":"not until ~; unless ~ first","formation":"Verb て-form + からでないと / からでなければ + negative or difficult result","note":"The main clause is negative or expresses impossibility: B can't happen before A.","examples":[{"ja":"宿題を終えてからでないと、遊びに行けない。","en":"I can't go out to play until I finish my homework."},{"ja":"実際に見てからでなければ、買うかどうか決められない。","en":"I can't decide whether to buy it until I actually see it."},{"ja":"両親に相談してからでないと、返事はできません。","en":"I can't give you an answer until I talk it over with my parents."}],"id":"n3g10"},{"pattern":"〜きり / 〜たきり","meaning":"only ~; (did ~) and nothing since","formation":"Noun + きり (only); Verb た-form + きり (〜ない)","note":"〜たきり means the situation hasn't changed since. Casual speech often uses っきり.","examples":[{"ja":"兄は朝出かけたきり、まだ帰ってこない。","en":"My brother went out this morning and still hasn't come back."},{"ja":"彼とは去年一度会ったきりだ。","en":"I've only met him once, last year."},{"ja":"二人きりで話したいことがある。","en":"There's something I want to talk about, just the two of us."}],"id":"n3g11"},{"pattern":"〜切る / 〜切れない","meaning":"to do ~ completely / unable to finish ~ (too much)","formation":"Verb ます-stem + 切る / 切れない","note":"〜切った + Noun can also mean 'utterly': 疲れ切った = completely exhausted.","examples":[{"ja":"一晩でこの本を読み切った。","en":"I read this whole book in one night."},{"ja":"料理が多すぎて、食べ切れない。","en":"There's too much food; I can't finish it all."},{"ja":"彼は疲れ切った顔をしていた。","en":"He looked completely exhausted."}],"id":"n3g12"},{"pattern":"〜かける / 〜かけの","meaning":"half-done; to start ~ but not finish","formation":"Verb ます-stem + かける / かけの + Noun / かけだ","note":"Shows an action begun but left unfinished, or something about to happen.","examples":[{"ja":"{机|つくえ}の上に読みかけの本がある。","en":"There's a half-read book on the desk."},{"ja":"彼女は何か言いかけて、{黙|だま}ってしまった。","en":"She started to say something, then fell silent."},{"ja":"食べかけのパンを{捨|す}てないでください。","en":"Please don't throw away the half-eaten bread."}],"id":"n3g13"},{"pattern":"〜っぱなし","meaning":"leaving ~ as is; keep ~ing (undesirably)","formation":"Verb ます-stem + っぱなし","note":"Usually critical: something left in a state it shouldn't be, or a tiring state continuing.","examples":[{"ja":"電気をつけっぱなしで寝てしまった。","en":"I fell asleep with the light left on."},{"ja":"窓を開けっぱなしにしないでください。","en":"Please don't leave the window open."},{"ja":"今日は一日中立ちっぱなしで疲れた。","en":"I was on my feet all day today and I'm tired."}],"id":"n3g14"},{"pattern":"〜たて","meaning":"freshly ~; just ~ed","formation":"Verb ます-stem + たて (+ の + Noun)","note":"Used with a limited set of verbs such as 焼く, 作る, 取る, 塗る, できる.","examples":[{"ja":"{焼|や}きたてのパンはとてもおいしい。","en":"Freshly baked bread is really delicious."},{"ja":"これは畑で取りたての野菜です。","en":"These are vegetables freshly picked from the field."},{"ja":"ペンキ{塗|ぬ}りたてなので、{触|さわ}らないでください。","en":"Wet paint. Please don't touch."}],"id":"n3g15"},{"pattern":"〜ついでに","meaning":"while (doing ~) anyway; taking the opportunity","formation":"Verb dictionary / た-form + ついでに; Noun + のついでに","note":"The second action is done conveniently along with the main one.","examples":[{"ja":"買い物のついでに、{郵便局|ゆうびんきょく}に寄った。","en":"While I was out shopping, I stopped by the post office."},{"ja":"駅へ行くついでに、この手紙を出してくれない？","en":"Since you're going to the station anyway, could you mail this letter?"},{"ja":"東京に来たついでに、友達に会った。","en":"Since I was in Tokyo, I took the chance to see a friend."}],"id":"n3g16"},{"pattern":"〜から〜にかけて","meaning":"from ~ through ~ (an approximate range of time or place)","formation":"Noun + から + Noun + にかけて","note":"The boundaries are vague, unlike 〜から〜まで, which marks exact start and end points.","examples":[{"ja":"明日は関東から東北にかけて雪が降るでしょう。","en":"Tomorrow it will probably snow from the Kanto region through Tohoku."},{"ja":"三月から四月にかけて、{桜|さくら}が{咲|さ}きます。","en":"Cherry blossoms bloom from March into April."},{"ja":"夜から朝にかけて、{気温|きおん}が下がる。","en":"The temperature drops from night through the morning."}],"id":"n3g17"},{"pattern":"〜ごとに","meaning":"every ~; each ~","formation":"Noun + ごとに; Verb dictionary form + ごとに","note":"Stresses regular repetition. Unlike おきに, 2日ごとに always means every two days.","examples":[{"ja":"オリンピックは四年ごとに開かれる。","en":"The Olympics are held every four years."},{"ja":"駅に着くごとに、電車の中の人が増えていった。","en":"At each station, more people got on the train."},{"ja":"グループごとに話し合ってください。","en":"Please discuss it in each group."}],"id":"n3g18"},{"pattern":"〜中 / 〜中","meaning":"中(ちゅう): in the middle of / currently ~; 中(じゅう): throughout ~","formation":"Noun + 中(ちゅう) (授業中, 会議中); Noun + 中(じゅう) (一日中, 世界中)","note":"ちゅう marks an ongoing activity; じゅう means all through a period or an entire area.","examples":[{"ja":"{授業中|じゅぎょうちゅう}は{携帯電話|けいたいでんわ}を使わないでください。","en":"Please don't use your cell phone during class."},{"ja":"父は今、会議中です。","en":"My father is in a meeting right now."},{"ja":"この歌は世界中で歌われている。","en":"This song is sung all over the world."}],"id":"n3g19"},{"pattern":"〜一方だ","meaning":"keep ~ing; more and more (one-way trend)","formation":"Verb dictionary form + 一方だ","note":"Used with change verbs (増える, 悪くなる). The trend is usually undesirable.","examples":[{"ja":"最近、物の値段は上がる一方だ。","en":"Prices just keep going up these days."},{"ja":"都会の人口は増える一方だ。","en":"The population of cities keeps on increasing."},{"ja":"雨は強くなる一方だった。","en":"The rain just kept getting heavier."}],"id":"n3g20"},{"pattern":"〜に{従|したが}って","meaning":"as ~ (one change brings another); in accordance with ~","formation":"Verb dictionary form + に従って; Noun + に従って","note":"Two meanings: proportional change (like につれて) or following rules or instructions.","examples":[{"ja":"北へ行くに{従|したが}って、寒くなる。","en":"The farther north you go, the colder it gets."},{"ja":"年をとるに{従|したが}って、体力が落ちてきた。","en":"As I've gotten older, my stamina has declined."},{"ja":"係の人の指示に{従|したが}って、行動してください。","en":"Please follow the staff's instructions."}],"id":"n3g21"},{"pattern":"〜につれて","meaning":"as ~ (gradual, proportional change)","formation":"Verb dictionary form + につれて; Noun (of change) + につれて","note":"Both clauses show gradual change; the main clause can't be a request or intention.","examples":[{"ja":"時間がたつにつれて、悲しみも消えていった。","en":"As time passed, my sadness faded away too."},{"ja":"日本語が上手になるにつれて、日本の生活が楽しくなった。","en":"As my Japanese improved, life in Japan became more enjoyable."},{"ja":"秋が深まるにつれて、木の葉が赤くなる。","en":"As autumn deepens, the leaves turn red."}],"id":"n3g22"},{"pattern":"〜に{伴|ともな}って","meaning":"along with ~; as ~ (accompanying change)","formation":"Noun + に伴って / に伴う + Noun; Verb dictionary form + のに伴って","note":"Formal, common in news. Typically used with nouns of change like 増加 or 変化.","examples":[{"ja":"人口の増加に{伴|ともな}って、住宅が足りなくなった。","en":"Along with the population increase, there is no longer enough housing."},{"ja":"台風の{接近|せっきん}に{伴|ともな}って、雨が強くなってきた。","en":"As the typhoon approaches, the rain has grown heavier."},{"ja":"経済の{発展|はってん}に{伴|ともな}って、生活が便利になった。","en":"Along with economic development, life has become more convenient."}],"id":"n3g23"},{"pattern":"〜とともに","meaning":"together with ~; as ~ (at the same time)","formation":"Noun + とともに; Verb dictionary form + とともに","note":"Formal equivalent of 〜と一緒に; also used for parallel change like につれて.","examples":[{"ja":"家族とともに新しい年を迎えた。","en":"I welcomed the new year together with my family."},{"ja":"年をとるとともに、{記憶力|きおくりょく}が弱くなる。","en":"As you age, your memory gets weaker."},{"ja":"社会の変化とともに、人々の考え方も変わってきた。","en":"Along with changes in society, people's ways of thinking have changed too."}],"id":"n3g24"},{"pattern":"〜ば〜ほど","meaning":"the more ~, the more ~","formation":"Verb ば-form + same Verb dictionary form + ほど; い-adj ければ + い-adj + ほど; な-adj なら + な-adj + なほど","note":"The same word is repeated. The ば-part can be dropped: 練習するほど上手になる.","examples":[{"ja":"考えれば考えるほど、わからなくなる。","en":"The more I think about it, the less I understand."},{"ja":"野菜は新しければ新しいほどおいしい。","en":"The fresher vegetables are, the better they taste."},{"ja":"説明は{簡単|かんたん}なら{簡単|かんたん}なほどいい。","en":"The simpler the explanation, the better."}],"id":"n3g25"},{"pattern":"〜ほど","meaning":"to the extent that ~; so ~ that ~","formation":"Verb dictionary / ない-form + ほど; い-adj + ほど; な-adj + なほど; Noun + ほど","note":"Shows the degree of a state with a vivid comparison, often exaggerated.","examples":[{"ja":"泣きたいほど悲しかった。","en":"I was so sad I wanted to cry."},{"ja":"今日は死ぬほど疲れた。","en":"I'm dead tired today."},{"ja":"足が痛くて、歩けないほどだった。","en":"My legs hurt so much I could hardly walk."}],"id":"n3g26"},{"pattern":"〜ほど〜はない","meaning":"nothing is as ~ as ~; ~ is the most ~","formation":"Noun + ほど + Adjective + Noun + はない (いない for people); Verb dictionary + ほど〜ことはない","note":"A way of expressing the superlative based on the speaker's feelings.","examples":[{"ja":"家族ほど大切なものはない。","en":"Nothing is as precious as family."},{"ja":"彼ほど親切な人はいない。","en":"There's no one as kind as him."},{"ja":"一人で食事をするほど{寂|さび}しいことはない。","en":"Nothing is as lonely as eating alone."}],"id":"n3g27"},{"pattern":"〜に{比|くら}べて","meaning":"compared to ~","formation":"Noun + に比べて / に比べると; Verb dictionary form + のに比べて","note":"Formal-sounding comparison; に比べると is slightly softer in conversation.","examples":[{"ja":"今年は去年に{比|くら}べて雨が多い。","en":"This year there's more rain compared to last year."},{"ja":"兄に{比|くら}べると、弟はよく話す。","en":"Compared to his older brother, the younger brother talks a lot."},{"ja":"電車で行くのに{比|くら}べて、バスは安い。","en":"Compared to going by train, the bus is cheaper."}],"id":"n3g28"},{"pattern":"〜わりに(は)","meaning":"for ~; considering ~ (unexpectedly)","formation":"Verb plain form / い-adj + わりに; な-adj + なわりに; Noun + のわりに","note":"The result differs from what you'd expect given the condition.","examples":[{"ja":"この店は値段のわりに、料理がおいしい。","en":"The food at this restaurant is good for the price."},{"ja":"彼はたくさん食べるわりに太らない。","en":"He doesn't gain weight considering how much he eats."},{"ja":"兄は年のわりに若く見える。","en":"My brother looks young for his age."}],"id":"n3g29"},{"pattern":"〜にしては","meaning":"for ~ (given a specific standard, unexpectedly)","formation":"Noun + にしては; Verb plain form + にしては","note":"Compared with わりに, にしては points to a specific fact (初めて, 子供) as the standard.","examples":[{"ja":"初めてにしては、よくできましたね。","en":"You did well for your first time."},{"ja":"小学生にしては、字がとても上手だ。","en":"For an elementary school student, his handwriting is very good."},{"ja":"十年も日本に住んでいるにしては、日本語が下手だ。","en":"For someone who has lived in Japan for ten years, his Japanese is poor."}],"id":"n3g30"},{"pattern":"〜おかげで","meaning":"thanks to ~ (good result)","formation":"Verb plain form / い-adj + おかげで; な-adj + なおかげで; Noun + のおかげで","note":"Expresses gratitude for a positive result. Used sarcastically, it can mean 'because of'.","examples":[{"ja":"先生のおかげで、試験に合格できました。","en":"Thanks to my teacher, I was able to pass the exam."},{"ja":"薬を飲んだおかげで、熱が下がった。","en":"Thanks to the medicine I took, my fever went down."},{"ja":"駅が近いおかげで、通勤が楽だ。","en":"Thanks to the station being close, my commute is easy."}],"id":"n3g31"},{"pattern":"〜せいで / 〜せいだ","meaning":"because of ~; ~'s fault (bad result)","formation":"Verb plain form / い-adj + せいで; な-adj + なせいで; Noun + のせいで","note":"Blames a cause for a negative outcome; the opposite of おかげで.","examples":[{"ja":"雨のせいで、試合が中止になった。","en":"The game was canceled because of the rain."},{"ja":"{寝坊|ねぼう}したせいで、電車に乗り遅れた。","en":"I missed the train because I overslept."},{"ja":"失敗したのは私のせいだ。","en":"It's my fault that we failed."}],"id":"n3g32"},{"pattern":"〜せいか","meaning":"perhaps because ~; maybe due to ~","formation":"Verb plain form / い-adj + せいか; な-adj + なせいか; Noun + のせいか","note":"The speaker isn't sure of the cause. The result is usually, but not always, negative.","examples":[{"ja":"年のせいか、最近疲れやすい。","en":"Maybe it's my age, but I get tired easily these days."},{"ja":"寝不足のせいか、頭が痛い。","en":"Perhaps because I didn't sleep enough, I have a headache."},{"ja":"暑いせいか、食欲がない。","en":"Maybe because of the heat, I have no appetite."}],"id":"n3g33"},{"pattern":"〜ため(に) (cause)","meaning":"because of ~; due to ~ (formal)","formation":"Verb plain form / い-adj + ため(に); な-adj + なため(に); Noun + のため(に)","note":"Formal reason, common in announcements. Don't confuse with ために meaning 'in order to'.","examples":[{"ja":"{事故|じこ}のため、電車が遅れています。","en":"The train is delayed due to an accident."},{"ja":"大雪が降ったために、学校が休みになった。","en":"School was closed because of heavy snow."},{"ja":"体が弱いため、{激|はげ}しい運動はできない。","en":"Because my health is weak, I can't do intense exercise."}],"id":"n3g34"},{"pattern":"〜ことから","meaning":"from the fact that ~; because ~ (basis for a name or judgment)","formation":"Verb / い-adj plain form + ことから; な-adj + な / である + ことから; Noun + である + ことから","note":"Often explains the origin of a name or the evidence for a conclusion.","examples":[{"ja":"{富士山|ふじさん}が見えることから、この町は「{富士見町|ふじみちょう}」と呼ばれている。","en":"Because Mt. Fuji can be seen from here, this town is called 'Fujimi-cho'."},{"ja":"顔がよく似ていることから、二人は兄弟だとわかった。","en":"From the fact that their faces looked alike, I knew the two were brothers."},{"ja":"道がぬれていることから、夜の間に雨が降ったことがわかる。","en":"Since the road is wet, we can tell it rained during the night."}],"id":"n3g35"},{"pattern":"〜からこそ","meaning":"precisely because ~","formation":"Plain form + からこそ","note":"Emphasizes that this reason, and no other, is what matters. Usually ends with のだ / んだ.","examples":[{"ja":"君のことを思っているからこそ、{厳|きび}しく言うんだ。","en":"It's precisely because I care about you that I'm being strict."},{"ja":"毎日{練習|れんしゅう}したからこそ、優勝できたのだ。","en":"It's precisely because we practiced every day that we won."},{"ja":"忙しいからこそ、休みが大切だ。","en":"Precisely because you're busy, rest is important."}],"id":"n3g36"},{"pattern":"〜からといって","meaning":"just because ~ (it doesn't mean ~)","formation":"Plain form + からといって + negative ending (〜わけではない, 〜とは限らない, 〜てはいけない)","note":"Denies an easy conclusion drawn from a single reason.","examples":[{"ja":"高いからといって、品質がいいとは限らない。","en":"Just because something is expensive doesn't mean it's good quality."},{"ja":"日本人だからといって、{敬語|けいご}が上手なわけではない。","en":"Being Japanese doesn't mean you're good at honorific language."},{"ja":"{嫌|きら}いだからといって、野菜を全然食べないのはよくない。","en":"Just because you dislike vegetables, it's not good to eat none at all."}],"id":"n3g37"},{"pattern":"〜わけだ","meaning":"that's why ~; no wonder ~; so it means ~","formation":"Verb / い-adj plain form + わけだ; な-adj + な + わけだ; Noun + の / である + わけだ","note":"Draws a natural conclusion from known facts; often 'No wonder!' after learning a reason.","examples":[{"ja":"彼は十年アメリカに住んでいた。英語が上手なわけだ。","en":"He lived in America for ten years. No wonder his English is good."},{"ja":"窓が開いている。寒いわけだ。","en":"The window is open. No wonder it's cold."},{"ja":"一日二時間勉強すれば、一週間で十四時間勉強するわけだ。","en":"If you study two hours a day, that means you study fourteen hours a week."}],"id":"n3g38"},{"pattern":"〜わけではない","meaning":"it doesn't mean that ~; it's not that ~","formation":"Verb / い-adj plain form + わけではない; な-adj + な + わけではない; Noun + という + わけではない","note":"Partial denial that softens a statement. Often used with 全部, いつも or 必ずしも.","examples":[{"ja":"肉が{嫌|きら}いなわけではないが、あまり食べない。","en":"It's not that I dislike meat, but I don't eat it much."},{"ja":"料理が全然できないわけではありません。","en":"It's not that I can't cook at all."},{"ja":"お金があれば幸せになれるというわけではない。","en":"Having money doesn't necessarily mean you can be happy."}],"id":"n3g39"},{"pattern":"〜わけがない","meaning":"there's no way ~; it can't be that ~","formation":"Verb / い-adj plain form + わけがない; な-adj + な + わけがない; Noun + の + わけがない","note":"Strong, subjective denial; similar to はずがない. Casual: わけない.","examples":[{"ja":"こんなに難しい問題が、子供にわかるわけがない。","en":"There's no way a child could understand such a difficult problem."},{"ja":"あの真面目な彼が{嘘|うそ}をつくわけがない。","en":"There's no way someone as honest as him would lie."},{"ja":"{練習|れんしゅう}しないで、上手になるわけがない。","en":"You can't possibly improve without practicing."}],"id":"n3g40"},{"pattern":"〜わけにはいかない","meaning":"cannot ~ (for social or moral reasons); 〜ないわけにはいかない = must ~","formation":"Verb dictionary form + わけにはいかない; Verb ない-form + わけにはいかない","note":"It's possible but not acceptable given circumstances; not about physical ability.","examples":[{"ja":"明日は試験だから、遊んでいるわけにはいかない。","en":"I have an exam tomorrow, so I can't just be playing around."},{"ja":"車で来たので、お酒を飲むわけにはいかない。","en":"I came by car, so I can't drink alcohol."},{"ja":"先生に頼まれたので、手伝わないわけにはいかない。","en":"My teacher asked me, so I can't refuse to help."}],"id":"n3g41"},{"pattern":"〜はずだった","meaning":"was supposed to ~ (but it didn't happen)","formation":"Verb / い-adj plain form + はずだった; な-adj + な + はずだった; Noun + の + はずだった","note":"Expresses that an expectation or plan didn't turn out; often followed by のに or が.","examples":[{"ja":"今日は友達が来るはずだったのに、来なかった。","en":"My friend was supposed to come today, but didn't."},{"ja":"電車は九時に着くはずだったが、三十分遅れた。","en":"The train was supposed to arrive at nine, but it was thirty minutes late."},{"ja":"本当は先週旅行に行くはずだった。","en":"I was actually supposed to go on a trip last week."}],"id":"n3g42"},{"pattern":"〜に違いない","meaning":"must be ~; there's no doubt that ~","formation":"Verb / い-adj plain form + に違いない; な-adj / Noun + に違いない (no だ)","note":"Strong conviction based on the speaker's reasoning; more written than 〜に決まっている.","examples":[{"ja":"電気が消えているから、{誰|だれ}もいないに違いない。","en":"The lights are off, so there must be no one there."},{"ja":"あの人は先生に違いない。","en":"That person must be a teacher."},{"ja":"彼女が作ったケーキなら、おいしいに違いない。","en":"If she made the cake, it must be delicious."}],"id":"n3g43"},{"pattern":"〜に決まっている","meaning":"it's certain that ~; of course ~","formation":"Verb / い-adj plain form + に決まっている; な-adj / Noun + に決まっている (no だ)","note":"Very confident, subjective and conversational; often sounds assertive.","examples":[{"ja":"そんなに食べたら、太るに決まっている。","en":"If you eat that much, you're bound to gain weight."},{"ja":"一人で行くより、みんなで行くほうが楽しいに決まっている。","en":"Going together is obviously more fun than going alone."},{"ja":"こんな時間に電話してくるのは、兄に決まっている。","en":"Anyone calling at this hour has to be my brother."}],"id":"n3g44"},{"pattern":"〜反面","meaning":"while ~, on the other hand ~ (two opposite sides of one thing)","formation":"Verb / い-adj plain form + 反面; な-adj + な / である + 反面; Noun + である + 反面","note":"Contrasts two sides of the same subject, e.g. a merit and a drawback.","examples":[{"ja":"都会の生活は便利な反面、ストレスも多い。","en":"City life is convenient, but on the other hand it's stressful."},{"ja":"この仕事は大変な反面、やりがいもある。","en":"This job is tough, but it's also rewarding."},{"ja":"スマホは役に立つ反面、使いすぎると目に悪い。","en":"Smartphones are useful, but using them too much is bad for your eyes."}],"id":"n3g45"},{"pattern":"〜一方(で)","meaning":"while ~; on the other hand ~ (contrast); at the same time","formation":"Verb / い-adj plain form + 一方(で); な-adj + な / である + 一方(で); Noun + である + 一方(で)","note":"Contrasts two different things, or shows two things done in parallel.","examples":[{"ja":"兄はスポーツが得意な一方で、弟は勉強が得意だ。","en":"The older brother is good at sports, while the younger one is good at studying."},{"ja":"彼は会社で働く一方で、夜は大学に通っている。","en":"He works at a company and at the same time attends university at night."},{"ja":"子供の数が{減|へ}る一方で、{高齢者|こうれいしゃ}は増えている。","en":"While the number of children is decreasing, the elderly population is growing."}],"id":"n3g46"},{"pattern":"〜くせに","meaning":"even though ~ (with criticism or contempt)","formation":"Verb / い-adj plain form + くせに; な-adj + な + くせに; Noun + の + くせに","note":"Expresses strong blame toward others; avoid with superiors. Not used about yourself.","examples":[{"ja":"知っているくせに、教えてくれない。","en":"Even though he knows, he won't tell me."},{"ja":"自分ではできないくせに、人には{文句|もんく}ばかり言う。","en":"He can't do it himself, yet he only complains about others."},{"ja":"彼は下手なくせに、いつも歌いたがる。","en":"Even though he's bad at it, he always wants to sing."}],"id":"n3g47"},{"pattern":"〜ながら(も)","meaning":"although ~; despite ~","formation":"Verb ます-stem + ながら(も); い-adj + ながら(も); な-adj / Noun + ながら(も)","note":"Concessive use, unlike 'while doing'. Common set phrases: 残念ながら, 狭いながらも.","examples":[{"ja":"{狭|せま}いながらも、自分の家が一番だ。","en":"Though it's small, my own home is the best."},{"ja":"彼は体が小さいながらも、力が強い。","en":"Though he is small, he is strong."},{"ja":"悪いと知りながら、{嘘|うそ}をついてしまった。","en":"Although I knew it was wrong, I told a lie."}],"id":"n3g48"},{"pattern":"〜としても","meaning":"even if ~ (supposing that ~)","formation":"Plain form + としても","note":"Assumes a hypothetical situation; the result doesn't change. Often with たとえ or もし.","examples":[{"ja":"今から急いだとしても、間に合わないだろう。","en":"Even if we hurry now, we probably won't make it."},{"ja":"たとえ{冗談|じょうだん}だとしても、そんなことを言ってはいけない。","en":"Even if it's a joke, you shouldn't say such a thing."},{"ja":"{宝|たから}くじが当たったとしても、仕事は辞めない。","en":"Even if I won the lottery, I wouldn't quit my job."}],"id":"n3g49"},{"pattern":"たとえ〜ても","meaning":"even if ~; no matter ~","formation":"たとえ + Verb て-form + も; い-adj くても; な-adj / Noun + でも","note":"たとえ adds emphasis to a hypothetical 〜ても clause.","examples":[{"ja":"たとえ雨が降っても、試合は行われます。","en":"Even if it rains, the game will be held."},{"ja":"たとえ反対されても、私は留学するつもりだ。","en":"Even if people oppose it, I intend to study abroad."},{"ja":"たとえ高くても、必要なものは買う。","en":"Even if it's expensive, I'll buy what I need."}],"id":"n3g50"},{"pattern":"〜といっても","meaning":"although I say ~; that said, ~ (it's not as much as it sounds)","formation":"Plain form + といっても","note":"Corrects an impression that the listener might get; the reality is smaller or simpler.","examples":[{"ja":"料理ができるといっても、{簡単|かんたん}なものだけです。","en":"I can cook, but only simple things."},{"ja":"休みといっても、一日だけだ。","en":"It's a holiday, but only for one day."},{"ja":"英語が話せるといっても、日常会話程度です。","en":"I can speak English, but only at the level of daily conversation."}],"id":"n3g51"},{"pattern":"〜かわりに","meaning":"instead of ~; in exchange for ~; but on the other hand","formation":"Verb plain form + かわりに; い-adj + かわりに; な-adj + なかわりに; Noun + のかわりに","note":"Substitution, exchange, or compensation (a downside balanced by an upside). Also written 代わりに.","examples":[{"ja":"母のかわりに、私が会議に出た。","en":"I attended the meeting in place of my mother."},{"ja":"英語を教えてもらうかわりに、日本語を教えてあげる。","en":"In exchange for teaching me English, I'll teach you Japanese."},{"ja":"この町は交通が不便なかわりに、自然が多い。","en":"This town has poor transportation, but on the other hand there's lots of nature."}],"id":"n3g52"},{"pattern":"〜に代わって","meaning":"in place of ~; on behalf of ~","formation":"Noun + に代わって / に代わり","note":"Formal; someone or something takes over another's role.","examples":[{"ja":"社長に代わって、私がご{挨拶|あいさつ}します。","en":"I will give the greeting on behalf of the company president."},{"ja":"最近は手紙に代わって、メールを使う人が多い。","en":"These days many people use email instead of letters."},{"ja":"病気の父に代わって、兄が店で働いている。","en":"My brother is working at the shop in place of our sick father."}],"id":"n3g53"},{"pattern":"〜に対して","meaning":"toward ~; against ~; in contrast to ~","formation":"Noun + に対して / に対する + Noun; Plain form + のに対して (contrast)","note":"Marks the target of an action or attitude; with のに対して it contrasts two facts.","examples":[{"ja":"先生に対して、そんな言葉を使ってはいけない。","en":"You must not use such language toward your teacher."},{"ja":"兄は背が高いのに対して、弟は低い。","en":"The older brother is tall, whereas the younger one is short."},{"ja":"{環境問題|かんきょうもんだい}に対する関心が高まっている。","en":"Interest in environmental issues is growing."}],"id":"n3g54"},{"pattern":"〜ないことはない","meaning":"it's not that ~ can't / isn't; ~ is possible (with reservation)","formation":"Verb ない-form + ことはない; い-adj くない + ことはない; な-adj / Noun + じゃない + ことはない","note":"A double negative giving a weak, hesitant yes. Also 〜ないこともない.","examples":[{"ja":"{辛|から}い料理は食べられないことはないが、あまり好きではない。","en":"It's not that I can't eat spicy food, but I don't really like it."},{"ja":"急げば間に合わないことはない。","en":"If we hurry, it's not impossible to make it in time."},{"ja":"少し高いが、買えないことはない。","en":"It's a little expensive, but it's not like I can't afford it."}],"id":"n3g55"},{"pattern":"〜とは限らない","meaning":"not necessarily ~; it isn't always the case that ~","formation":"Plain form + とは限らない (often with 必ずしも, いつも, 誰でも)","note":"Points out exceptions to a common assumption.","examples":[{"ja":"高い物が必ずしもいい物とは限らない。","en":"Expensive things are not necessarily good things."},{"ja":"先生がいつも正しいとは限らない。","en":"Teachers aren't always right."},{"ja":"日本人がみんな{寿司|すし}が好きだとは限らない。","en":"Not all Japanese people necessarily like sushi."}],"id":"n3g56"},{"pattern":"〜というより","meaning":"rather than ~; more ~ than ~","formation":"Plain form + というより (Noun / な-adj usually without だ)","note":"Corrects a description with a more accurate one. Often followed by むしろ.","examples":[{"ja":"今日は{暖|あたた}かいというより暑い。","en":"Today it's hot rather than warm."},{"ja":"彼は友達というより家族のような存在だ。","en":"He's more like family than a friend."},{"ja":"この部屋は部屋というより物置だ。","en":"This room is more of a storage closet than a room."}],"id":"n3g57"},{"pattern":"〜上に","meaning":"on top of ~; in addition to ~; besides ~","formation":"Verb / い-adj plain form + 上に; な-adj + な / である + 上に; Noun + の / である + 上に","note":"Adds a second point in the same direction (good + good or bad + bad).","examples":[{"ja":"この店は安い上に、おいしい。","en":"This restaurant is cheap, and on top of that, delicious."},{"ja":"道に迷った上に、雨まで降ってきた。","en":"On top of getting lost, it even started to rain."},{"ja":"彼女は親切な上に、頭もいい。","en":"She's kind, and smart as well."}],"id":"n3g58"},{"pattern":"〜に加えて","meaning":"in addition to ~","formation":"Noun + に加えて","note":"Formal way to add one more item; often followed by も.","examples":[{"ja":"英語に加えて、中国語も勉強している。","en":"In addition to English, I'm also studying Chinese."},{"ja":"強い風に加えて、雨も降り出した。","en":"In addition to the strong wind, it started to rain too."},{"ja":"{授業料|じゅぎょうりょう}に加えて、教科書代もかかる。","en":"In addition to tuition, textbooks cost money too."}],"id":"n3g59"},{"pattern":"〜ばかりでなく / 〜だけでなく","meaning":"not only ~ but also ~","formation":"Verb / い-adj plain form; な-adj + な; Noun + ばかりでなく / だけでなく (+ 〜も)","note":"The second clause usually contains も. ばかりでなく is slightly more formal.","examples":[{"ja":"彼は英語ばかりでなく、フランス語も話せる。","en":"He can speak not only English but also French."},{"ja":"この本は子供だけでなく、大人にも人気がある。","en":"This book is popular not only with children but with adults too."},{"ja":"彼女は歌が上手なだけでなく、ダンスもうまい。","en":"She's not only a good singer, but a good dancer too."}],"id":"n3g60"},{"pattern":"〜ばかりか","meaning":"not only ~ but even ~ (surprising addition)","formation":"Verb / い-adj plain form; な-adj + な; Noun + ばかりか (+ 〜も / 〜まで / 〜さえ)","note":"Stronger than ばかりでなく; the added point is more extreme or unexpected.","examples":[{"ja":"彼は{謝|あやま}らないばかりか、私のせいにした。","en":"Not only did he not apologize, he even blamed me."},{"ja":"{風邪|かぜ}をひいたばかりか、{財布|さいふ}までなくしてしまった。","en":"Not only did I catch a cold, I even lost my wallet."},{"ja":"この店は安いばかりか、サービスもいい。","en":"This shop is not only cheap, its service is good too."}],"id":"n3g61"},{"pattern":"〜はもちろん","meaning":"not to mention ~; ~ of course, and also ~","formation":"Noun + はもちろん(のこと)","note":"The first item is obvious; the second is added. Usually followed by も.","examples":[{"ja":"この料理は子供はもちろん、大人も喜ぶ。","en":"Kids love this dish, of course, and adults do too."},{"ja":"彼は日本語はもちろん、{韓国語|かんこくご}も話せる。","en":"He speaks Japanese, of course, and Korean as well."},{"ja":"週末はもちろん、平日もこの店は{混|こ}んでいる。","en":"This shop is crowded on weekdays, not to mention weekends."}],"id":"n3g62"},{"pattern":"〜に関して / 〜に関する","meaning":"regarding ~; related to ~","formation":"Noun + に関して / に関する + Noun","note":"More formal than について; に関する modifies a noun.","examples":[{"ja":"{事故|じこ}に関して、警察が調べている。","en":"The police are investigating the accident."},{"ja":"日本の{歴史|れきし}に関する本を探しています。","en":"I'm looking for a book on Japanese history."},{"ja":"{新製品|しんせいひん}に関するお問い合わせは、こちらまでどうぞ。","en":"Please direct inquiries about new products here."}],"id":"n3g63"},{"pattern":"〜にとって","meaning":"for ~; from the standpoint of ~","formation":"Noun (person / group) + にとって","note":"Followed by an evaluation (大切, 難しい). Not used for actions done toward someone (use に対して).","examples":[{"ja":"私にとって、家族が一番大切だ。","en":"For me, family is the most important thing."},{"ja":"この写真は彼にとって大事な思い出だ。","en":"This photo is a precious memory for him."},{"ja":"外国人にとって、漢字は難しい。","en":"Kanji is difficult for foreigners."}],"id":"n3g64"},{"pattern":"〜として","meaning":"as ~ (in the role or capacity of ~)","formation":"Noun + として / としての + Noun","note":"Shows status, role or purpose. としては = 'as far as ~ is concerned'.","examples":[{"ja":"彼は留学生として日本に来た。","en":"He came to Japan as an exchange student."},{"ja":"この部屋は会議室として使われている。","en":"This room is used as a meeting room."},{"ja":"親として、子供のことが心配だ。","en":"As a parent, I worry about my child."}],"id":"n3g65"},{"pattern":"〜によって / 〜による","meaning":"by ~; depending on ~; due to ~; by means of ~","formation":"Noun + によって / により / による + Noun","note":"Marks the agent in passive sentences, a cause, a means, or variation (国によって違う).","examples":[{"ja":"この小説は有名な作家によって書かれた。","en":"This novel was written by a famous author."},{"ja":"国によって、習慣が違う。","en":"Customs differ depending on the country."},{"ja":"{地震|じしん}による{被害|ひがい}は大きかった。","en":"The damage caused by the earthquake was severe."}],"id":"n3g66"},{"pattern":"〜を中心に","meaning":"centered on ~; focusing on ~","formation":"Noun + を中心に / を中心として / を中心とした + Noun","note":"Marks the central point, main focus or core group of something.","examples":[{"ja":"駅を中心に、店が{並|なら}んでいる。","en":"Shops are lined up around the station."},{"ja":"この{授業|じゅぎょう}では会話を中心に勉強します。","en":"In this class we'll focus mainly on conversation."},{"ja":"若者を中心に、この歌が流行している。","en":"This song is popular, especially among young people."}],"id":"n3g67"},{"pattern":"〜を通じて / 〜を通して","meaning":"through ~ (means or intermediary); throughout ~ (a whole period)","formation":"Noun + を通じて / を通して","note":"Both share the two meanings; を通して often stresses deliberate effort or experience.","examples":[{"ja":"友人を通じて、彼女と知り合った。","en":"I got to know her through a friend."},{"ja":"この{地域|ちいき}は一年を通じて{暖|あたた}かい。","en":"This region is warm all year round."},{"ja":"留学を通して、多くのことを学んだ。","en":"I learned many things through studying abroad."}],"id":"n3g68"},{"pattern":"〜をはじめ","meaning":"starting with ~; including ~ (as a main example)","formation":"Noun + をはじめ / をはじめ(として) / をはじめとする + Noun","note":"Gives a representative example, followed by a broader group.","examples":[{"ja":"京都には{金閣寺|きんかくじ}をはじめ、有名なお{寺|てら}がたくさんある。","en":"Kyoto has many famous temples, starting with Kinkaku-ji."},{"ja":"校長先生をはじめ、多くの先生が出席した。","en":"Many teachers attended, including the principal."},{"ja":"日本には{寿司|すし}をはじめ、おいしい料理がたくさんある。","en":"Japan has lots of delicious food, sushi being a prime example."}],"id":"n3g69"},{"pattern":"〜をもとに","meaning":"based on ~; using ~ as a basis","formation":"Noun + をもとに / をもとにして / をもとにした + Noun","note":"The noun is the source material or data from which something is made.","examples":[{"ja":"この映画は本当の話をもとに作られた。","en":"This movie was made based on a true story."},{"ja":"アンケートの結果をもとに、新しい商品を考えた。","en":"We came up with a new product based on the survey results."},{"ja":"自分の経験をもとにして、小説を書いた。","en":"I wrote a novel based on my own experiences."}],"id":"n3g70"},{"pattern":"〜をこめて","meaning":"with (feeling) ~; full of ~","formation":"Noun (feeling) + をこめて / をこめた + Noun","note":"Used with nouns like 心, 愛, 感謝, 願い. Also written 〜を込めて.","examples":[{"ja":"心をこめて、手紙を書きました。","en":"I wrote the letter with all my heart."},{"ja":"母は愛をこめてお{弁当|べんとう}を作ってくれた。","en":"My mother lovingly made me a boxed lunch."},{"ja":"{感謝|かんしゃ}の気持ちをこめて、花を{贈|おく}った。","en":"I gave her flowers to express my gratitude."}],"id":"n3g71"},{"pattern":"〜をきっかけに","meaning":"with ~ as the trigger; taking ~ as an opportunity","formation":"Noun + をきっかけに / をきっかけとして; Verb た-form + のをきっかけに","note":"The event prompts a new beginning or change.","examples":[{"ja":"留学をきっかけに、料理を始めた。","en":"Studying abroad was what got me started cooking."},{"ja":"病気をきっかけに、たばこをやめた。","en":"Getting sick prompted me to quit smoking."},{"ja":"日本のアニメを見たのをきっかけに、日本語を勉強し始めた。","en":"Watching Japanese anime led me to start studying Japanese."}],"id":"n3g72"},{"pattern":"〜というと / 〜といえば","meaning":"speaking of ~; when it comes to ~","formation":"Noun + というと / といえば / といったら","note":"Brings up a topic or the first thing associated with it; also used to pick up what someone just said.","examples":[{"ja":"日本の山といえば、やっぱり{富士山|ふじさん}だ。","en":"When it comes to mountains in Japan, it has to be Mt. Fuji."},{"ja":"夏というと、花火を思い出す。","en":"Summer makes me think of fireworks."},{"ja":"田中さんといえば、最近結婚したそうですね。","en":"Speaking of Mr. Tanaka, I heard he recently got married."}],"id":"n3g73"},{"pattern":"〜というのは","meaning":"what ~ means is ~; ~ is (definition or explanation)","formation":"Noun / phrase + というのは + 〜のことだ / 〜という意味だ / 〜ものだ","note":"Introduces a term to define, or a statement to explain or comment on.","examples":[{"ja":"「スマホ」というのは、スマートフォンのことです。","en":"'Sumaho' means smartphone."},{"ja":"友達というのは、困ったときに助け合うものだ。","en":"Friends are people who help each other when in trouble."},{"ja":"彼が来ないというのは、本当ですか。","en":"Is it true that he isn't coming?"}],"id":"n3g74"},{"pattern":"〜ということだ","meaning":"I heard that ~; they say ~; that means ~","formation":"Plain form + ということだ","note":"Hearsay, like そうだ but more formal; it can also state a conclusion: 'in other words ~'.","examples":[{"ja":"天気予報によると、今年の夏は暑くなるということだ。","en":"According to the forecast, this summer will be hot."},{"ja":"部長は午後から会社に戻るということです。","en":"I'm told the manager will be back at the office in the afternoon."},{"ja":"返事がないということは、{興味|きょうみ}がないということだ。","en":"No reply means they're not interested."}],"id":"n3g75"},{"pattern":"〜とか","meaning":"I heard something like ~ (vague hearsay)","formation":"Plain form + とか","note":"Less certain than そうだ; the speaker only half-remembers what they heard.","examples":[{"ja":"田中さんは来月結婚するとか。","en":"I heard Tanaka-san is getting married next month or something."},{"ja":"北海道ではもう雪が降ったとか。","en":"I heard it's already snowed in Hokkaido."},{"ja":"駅前に新しいレストランができたとかで、行列ができている。","en":"Apparently a new restaurant opened in front of the station, and there's a line."}],"id":"n3g76"},{"pattern":"〜向き / 〜向け","meaning":"向き: suitable for ~; 向け: intended / made for ~","formation":"Noun + 向き(の / だ); Noun + 向け(の / だ)","note":"向き = it happens to suit; 向け = it was designed for that target.","examples":[{"ja":"この料理は{辛|から}くないので、子供向きだ。","en":"This dish isn't spicy, so it's suitable for children."},{"ja":"これは日本語を勉強している外国人向けの{雑誌|ざっし}だ。","en":"This is a magazine for foreigners studying Japanese."},{"ja":"この仕事は体力のある人向きだ。","en":"This job is suited to people with physical stamina."}],"id":"n3g77"},{"pattern":"〜的","meaning":"-ic, -al; in terms of ~ (turns a noun into a な-adjective)","formation":"Noun + 的 (+ な + Noun / + に + Verb)","note":"Mostly attaches to Sino-Japanese nouns: 経済的, 積極的, 個人的.","examples":[{"ja":"彼は{積極的|せっきょくてき}に意見を言う。","en":"He actively gives his opinions."},{"ja":"経済的な理由で、大学をやめた。","en":"I quit university for financial reasons."},{"ja":"{個人的|こじんてき}には、この案に賛成です。","en":"Personally, I agree with this plan."}],"id":"n3g78"},{"pattern":"〜っぽい","meaning":"-ish; like ~; tends to ~","formation":"Noun / い-adj stem / Verb ます-stem + っぽい","note":"Casual. Often negative: 子供っぽい = childish, 忘れっぽい = forgetful. Conjugates like an い-adjective.","examples":[{"ja":"彼は大人なのに、子供っぽいところがある。","en":"He's an adult, but he has a childish side."},{"ja":"年のせいか、最近忘れっぽくなった。","en":"Maybe it's my age, but I've become forgetful lately."},{"ja":"白っぽいシャツを探しています。","en":"I'm looking for a whitish shirt."}],"id":"n3g79"},{"pattern":"〜気味","meaning":"slightly ~; a touch of ~ (usually negative)","formation":"Noun / Verb ます-stem + 気味 (だ / の + Noun)","note":"Describes a mild tendency or symptom: 風邪気味, 太り気味, 疲れ気味.","examples":[{"ja":"{風邪|かぜ}気味なので、今日は早く寝ます。","en":"I feel like I'm coming down with a cold, so I'll go to bed early today."},{"ja":"最近少し太り気味だ。","en":"Lately I've been putting on a bit of weight."},{"ja":"仕事が忙しくて、疲れ気味です。","en":"Work is busy and I'm a bit tired."}],"id":"n3g80"},{"pattern":"〜がち","meaning":"tend to ~; prone to ~ (usually negative)","formation":"Verb ます-stem + がち; Noun + がち","note":"Describes something that happens often, usually undesirable: 遅れがち, 病気がち.","examples":[{"ja":"冬は{風邪|かぜ}をひきがちだ。","en":"I tend to catch colds in winter."},{"ja":"彼は病気がちで、よく学校を休む。","en":"He's often sick and frequently misses school."},{"ja":"忙しいと、食事が{不規則|ふきそく}になりがちだ。","en":"When you're busy, your meals tend to become irregular."}],"id":"n3g81"},{"pattern":"〜だらけ","meaning":"full of ~; covered with ~ (unpleasant)","formation":"Noun + だらけ","note":"Something is covered or filled with an undesirable thing: 泥だらけ, 間違いだらけ.","examples":[{"ja":"子供たちは{泥|どろ}だらけになって遊んでいた。","en":"The children were playing and got covered in mud."},{"ja":"この作文は間違いだらけだ。","en":"This essay is full of mistakes."},{"ja":"部屋がごみだらけで、座る場所もない。","en":"The room is full of trash; there's nowhere even to sit."}],"id":"n3g82"},{"pattern":"〜らしい (typical)","meaning":"typical of ~; befitting ~; like a true ~","formation":"Noun + らしい (らしく + Verb)","note":"Different from hearsay らしい: here it means having the ideal qualities of the noun.","examples":[{"ja":"今日は春らしい{暖|あたた}かい日だ。","en":"Today is a warm, spring-like day."},{"ja":"{文句|もんく}を言うなんて、君らしくないね。","en":"Complaining like that isn't like you."},{"ja":"彼はいつも自分らしく生きている。","en":"He always lives true to himself."}],"id":"n3g83"},{"pattern":"まるで〜ようだ","meaning":"just like ~; as if ~","formation":"まるで + Plain form + ようだ / みたいだ (Noun + のようだ; な-adj + なようだ)","note":"まるで strengthens a comparison with something it is not actually.","examples":[{"ja":"彼の日本語はまるで日本人のようだ。","en":"His Japanese is just like a native speaker's."},{"ja":"まるで夢を見ているようだった。","en":"It was as if I were dreaming."},{"ja":"今日は{暖|あたた}かくて、まるで春みたいだ。","en":"It's so warm today, it's just like spring."}],"id":"n3g84"},{"pattern":"〜べき","meaning":"should ~; ought to ~","formation":"Verb dictionary form + べきだ / べきではない / べき + Noun (する → すべき / するべき)","note":"Strong moral or general obligation; べきだった expresses regret or criticism about the past.","examples":[{"ja":"約束は守るべきだ。","en":"You should keep your promises."},{"ja":"人の悪口を言うべきではない。","en":"You shouldn't speak ill of others."},{"ja":"もっと早く病院に行くべきだった。","en":"I should have gone to the hospital sooner."}],"id":"n3g85"},{"pattern":"〜ことだ","meaning":"you should ~; the best thing is to ~ (advice)","formation":"Verb dictionary / ない-form + ことだ","note":"Advice from a superior or experienced person; sounds a bit authoritative.","examples":[{"ja":"日本語が上手になりたければ、毎日話すことだ。","en":"If you want to get good at Japanese, you should speak it every day."},{"ja":"{風邪|かぜ}を早く治したいなら、ゆっくり休むことだ。","en":"If you want to get over your cold quickly, the best thing is to rest."},{"ja":"危ない所には近づかないことだ。","en":"You'd better stay away from dangerous places."}],"id":"n3g86"},{"pattern":"〜ことはない","meaning":"there's no need to ~","formation":"Verb dictionary form + ことはない","note":"Reassures or encourages someone. Similar to 〜必要はない.","examples":[{"ja":"心配することはないよ。","en":"There's no need to worry."},{"ja":"まだ時間があるから、急ぐことはない。","en":"There's still time, so there's no need to hurry."},{"ja":"君が{謝|あやま}ることはない。","en":"You don't need to apologize."}],"id":"n3g87"},{"pattern":"〜しかない","meaning":"have no choice but to ~","formation":"Verb dictionary form + しかない","note":"There is only one option left. Different from Noun + しか〜ない ('only').","examples":[{"ja":"終電が出てしまったので、歩いて帰るしかない。","en":"The last train has left, so I have no choice but to walk home."},{"ja":"{誰|だれ}も手伝ってくれないなら、自分でやるしかない。","en":"If no one will help, I'll just have to do it myself."},{"ja":"もう決まったことだから、やるしかない。","en":"It's already been decided, so we just have to do it."}],"id":"n3g88"},{"pattern":"〜ようがない","meaning":"there's no way to ~; impossible to ~","formation":"Verb ます-stem + ようがない (する → しようがない)","note":"There is no method or means available. With する nouns: 連絡のしようがない.","examples":[{"ja":"住所がわからないので、{連絡|れんらく}のしようがない。","en":"I don't know the address, so there's no way to contact them."},{"ja":"こんなに{壊|こわ}れていたら、直しようがない。","en":"If it's this broken, there's no way to fix it."},{"ja":"今の気持ちは、言葉では言い表しようがない。","en":"There's no way to put my feelings right now into words."}],"id":"n3g89"},{"pattern":"〜ものだ","meaning":"it's natural that ~; one should ~ (general truth or social expectation)","formation":"Verb / い-adj plain form + ものだ; な-adj + な + ものだ","note":"States how things naturally are, or what is socially expected. Casual: もんだ.","examples":[{"ja":"人は{誰|だれ}でも間違えるものだ。","en":"Everyone makes mistakes."},{"ja":"時間がたつのは早いものだ。","en":"Time really does fly."},{"ja":"目上の人には{敬語|けいご}を使うものだ。","en":"You're supposed to use polite language with your superiors."}],"id":"n3g90"},{"pattern":"〜たものだ","meaning":"used to ~ (fond recollection)","formation":"Verb た-form + ものだ","note":"Nostalgic memories of repeated past actions; often with よく and 昔 / 子供のころ.","examples":[{"ja":"子供のころ、よくこの川で泳いだものだ。","en":"When I was a child, I often used to swim in this river."},{"ja":"学生のときは、朝まで友達と話したものだ。","en":"When I was a student, I used to talk with friends until morning."},{"ja":"昔はよく家族で旅行したものだ。","en":"We used to travel as a family a lot in the old days."}],"id":"n3g91"},{"pattern":"〜もの / 〜もん","meaning":"because ~ (personal excuse, casual)","formation":"Plain form + もの / もん (often 〜んだもの / 〜んだもん, with だって)","note":"Justifies oneself in casual speech; sounds childish or soft. Avoid in formal situations.","examples":[{"ja":"だって、知らなかったんだもん。","en":"Well, I didn't know!"},{"ja":"今日は出かけたくない。疲れているもの。","en":"I don't want to go out today. I'm tired, after all."},{"ja":"食べないよ。{嫌|きら}いなんだもん。","en":"I'm not eating it. I don't like it!"}],"id":"n3g92"},{"pattern":"〜ことか","meaning":"how ~!; so very ~ (strong emotion)","formation":"Plain form + ことか (な-adj + な / である); often with どんなに, どれほど, 何度","note":"Exclamatory, a bit literary. The question word emphasizes how intense the feeling is.","examples":[{"ja":"合格の知らせを聞いて、どんなにうれしかったことか。","en":"How happy I was to hear I had passed!"},{"ja":"遅刻しないようにと、何度注意したことか。","en":"How many times have I warned you not to be late!"},{"ja":"彼に会える日を、どれほど待っていたことか。","en":"How long I have waited for the day I could see him!"}],"id":"n3g93"},{"pattern":"〜てしょうがない / 〜てしかたがない","meaning":"extremely ~; can't help ~ (feeling)","formation":"Verb て-form / い-adj くて / な-adj で + しょうがない / しかたがない","note":"Feelings or sensations too strong to control. しょうがない is the casual form.","examples":[{"ja":"毎日暑くてしょうがない。","en":"It's unbearably hot every day."},{"ja":"試験の結果が気になってしかたがない。","en":"I can't stop worrying about my exam results."},{"ja":"友達がいなくて、{寂|さび}しくてしょうがない。","en":"I have no friends here, and I'm terribly lonely."}],"id":"n3g94"},{"pattern":"〜てたまらない","meaning":"unbearably ~; dying to ~","formation":"Verb て-form / い-adj くて / な-adj で + たまらない","note":"The speaker's own strong feelings or sensations, e.g. 痛い, 会いたい, うれしい.","examples":[{"ja":"歯が痛くてたまらない。","en":"My tooth hurts unbearably."},{"ja":"国の家族に会いたくてたまらない。","en":"I'm dying to see my family back home."},{"ja":"試験に合格して、うれしくてたまらない。","en":"I passed the exam and I'm overjoyed."}],"id":"n3g95"},{"pattern":"〜てならない","meaning":"can't help feeling ~; extremely ~ (spontaneous feeling)","formation":"Verb て-form / い-adj くて / な-adj で + ならない","note":"More formal than てしょうがない; common with 思える, 気がする, 心配, 残念.","examples":[{"ja":"一人で暮らしている母のことが心配でならない。","en":"I can't stop worrying about my mother living alone."},{"ja":"彼が{嘘|うそ}をついているように思えてならない。","en":"I can't help feeling that he's lying."},{"ja":"子供のころが{懐|なつ}かしくてならない。","en":"I feel terribly nostalgic for my childhood."}],"id":"n3g96"},{"pattern":"〜気がする","meaning":"to have a feeling that ~","formation":"Plain form + 気がする; 〜ような気がする; Noun + の / のような + 気がする","note":"Softens a statement into a personal impression; ような気がする is especially common.","examples":[{"ja":"{誰|だれ}かに見られているような気がする。","en":"I feel like someone is watching me."},{"ja":"明日は雨が降る気がする。","en":"I have a feeling it will rain tomorrow."},{"ja":"この人には前にも会ったことがあるような気がする。","en":"I feel like I've met this person before."}],"id":"n3g97"},{"pattern":"〜てみせる","meaning":"to show (someone) how to ~; to definitely ~ (strong resolve)","formation":"Verb て-form + みせる","note":"Two uses: demonstrating an action, or declaring 'I'll show you I can do it'.","examples":[{"ja":"先生が漢字の書き方を書いてみせた。","en":"The teacher demonstrated how to write the kanji."},{"ja":"次の試合では必ず勝ってみせる。","en":"I'll definitely win the next match, you'll see."},{"ja":"来年こそ合格してみせます。","en":"Next year, I'll pass for sure."}],"id":"n3g98"},{"pattern":"〜ようとしない","meaning":"won't (even try to) ~; refuses to ~","formation":"Verb volitional form + としない","note":"Describes someone else's unwillingness, not the speaker's own.","examples":[{"ja":"息子は野菜を食べようとしない。","en":"My son refuses to eat vegetables."},{"ja":"彼は自分の間違いを認めようとしない。","en":"He won't admit his mistake."},{"ja":"何度呼んでも、猫は出てこようとしない。","en":"No matter how many times I call, the cat won't come out."}],"id":"n3g99"},{"pattern":"〜ふりをする","meaning":"to pretend to ~","formation":"Verb plain form / い-adj + ふりをする; な-adj + な + ふりをする; Noun + の + ふりをする","note":"Acting as if something were true when it isn't.","examples":[{"ja":"彼は聞こえないふりをした。","en":"He pretended not to hear."},{"ja":"本当は知っているのに、知らないふりをする。","en":"He actually knows, but pretends not to."},{"ja":"弟は病気のふりをして、学校を休んだ。","en":"My little brother pretended to be sick and skipped school."}],"id":"n3g100"},{"pattern":"〜つもりで","meaning":"with the intention of ~; as if ~ (imagining oneself in a situation)","formation":"Verb dictionary / た-form + つもりで; Noun + のつもりで","note":"〜たつもりで means acting as if something had happened, though it hasn't.","examples":[{"ja":"旅行に行ったつもりで、そのお金を{貯金|ちょきん}した。","en":"I pretended I'd gone on the trip and saved that money instead."},{"ja":"先生になったつもりで、説明してみてください。","en":"Try explaining it as if you were the teacher."},{"ja":"{冗談|じょうだん}のつもりで言ったのに、彼女を怒らせてしまった。","en":"I meant it as a joke, but I made her angry."}],"id":"n3g101"},{"pattern":"〜ことにしている","meaning":"to make it a rule to ~; to make a habit of ~","formation":"Verb dictionary / ない-form + ことにしている","note":"A personal rule decided by oneself, compared with ことになっている for external rules.","examples":[{"ja":"毎朝、三十分散歩することにしている。","en":"I make it a rule to take a thirty-minute walk every morning."},{"ja":"健康のために、夜は{甘|あま}いものを食べないことにしている。","en":"For my health, I make a point of not eating sweets at night."},{"ja":"寝る前にスマホを見ないことにしている。","en":"I make a habit of not looking at my phone before bed."}],"id":"n3g102"},{"pattern":"〜ことになっている","meaning":"it is arranged / scheduled / a rule that ~","formation":"Verb dictionary / ない-form + ことになっている","note":"Plans, schedules or rules decided by others or by an organization.","examples":[{"ja":"明日、部長と会うことになっている。","en":"I'm scheduled to meet the department manager tomorrow."},{"ja":"この学校では、制服を着ることになっている。","en":"At this school, students are required to wear uniforms."},{"ja":"図書館の中では、食事をしてはいけないことになっている。","en":"The rule is that you can't eat inside the library."}],"id":"n3g103"},{"pattern":"〜てもらいたい / 〜ていただきたい","meaning":"I'd like (someone) to ~","formation":"Verb て-form + もらいたい / いただきたい","note":"A wish for someone else's action; ていただきたい is the polite form.","examples":[{"ja":"この仕事は君にやってもらいたい。","en":"I'd like you to do this job."},{"ja":"皆様にぜひ来ていただきたいです。","en":"We'd really like all of you to come."},{"ja":"もう少しゆっくり話していただきたいのですが。","en":"I'd like you to speak a little more slowly, please."}],"id":"n3g104"},{"pattern":"〜させてもらう / 〜させていただく","meaning":"to be allowed to ~; (humbly) I will ~","formation":"Verb causative て-form + もらう / いただく","note":"Asks permission or humbly announces one's own action. させていただく is very common in business.","examples":[{"ja":"体調が悪いので、今日は休ませていただきます。","en":"I'm not feeling well, so I'll take the day off today."},{"ja":"ちょっと電話を使わせてもらえませんか。","en":"Could you let me use the phone for a moment?"},{"ja":"それでは、発表を始めさせていただきます。","en":"Well then, I'll begin my presentation."}],"id":"n3g105"},{"pattern":"〜に向かって","meaning":"toward; facing; (speaking) to ~","formation":"Noun + に向かって / に向かい","note":"Shows a physical direction, or the person you are speaking to. For a goal or an event you are preparing for, N2 〜に向けて is more natural.","examples":[{"ja":"子供たちは海に向かって走っていった。","en":"The children ran off toward the sea."},{"ja":"親に向かってそんな言い方をしてはいけない。","en":"You mustn't speak to your parents like that."}],"id":"n3g106"},{"pattern":"〜っけ","meaning":"was it ~? (trying to recall or confirm)","formation":"Plain form (often past) + っけ; Noun / な-adj + だっけ / でしたっけ","note":"Casual; asks the listener or oneself to confirm something half-remembered.","examples":[{"ja":"会議は何時からだっけ？","en":"What time does the meeting start again?"},{"ja":"あの人の名前、何だっけ。","en":"What was that person's name again?"},{"ja":"前にこの話、したっけ？","en":"Did I tell you this story before?"}],"id":"n3g107"},{"pattern":"〜じゃないか / 〜ではないか","meaning":"isn't it ~! (surprise, reproach); let's ~ (with volitional)","formation":"Plain form + じゃないか (Noun / な-adj without だ); Verb volitional + じゃないか / ではないか","note":"Falling intonation; with volitional form it's a strong invitation, often in speeches.","examples":[{"ja":"約束と違うじゃないか。","en":"This isn't what we agreed on!"},{"ja":"{久|ひさ}しぶりじゃないか。元気だった？","en":"Long time no see! How have you been?"},{"ja":"みんなで{頑張|がんば}ろうではないか。","en":"Let's all do our best together!"}],"id":"n3g108"},{"pattern":"〜なんて / 〜なんか","meaning":"things like ~; such a thing as ~ (belittling or surprise)","formation":"Noun + なんか / なんて; Plain form + なんて","note":"Shows contempt, modesty or surprise. なんか mainly follows nouns; なんて can follow clauses.","examples":[{"ja":"彼が試験に落ちるなんて、信じられない。","en":"I can't believe he failed the exam."},{"ja":"私なんか、まだまだです。","en":"Someone like me still has a long way to go."},{"ja":"お化けなんているわけがない。","en":"There's no way ghosts exist."}],"id":"n3g109"},{"pattern":"〜こそ","meaning":"precisely ~; this very ~ (emphasis)","formation":"Noun + こそ; Verb て-form + こそ; 〜からこそ","note":"Emphasizes one element as the important one. こちらこそ = 'Likewise / I'm the one who should ~'.","examples":[{"ja":"今年こそ日本語能力試験に合格したい。","en":"This year, for sure, I want to pass the JLPT."},{"ja":"A：よろしくお願いします。B：こちらこそ。","en":"A: Nice to meet you. B: The pleasure is mine."},{"ja":"失敗してこそ、人は成長する。","en":"It's precisely by failing that people grow."}],"id":"n3g110"},{"pattern":"〜さえ","meaning":"even ~","formation":"Noun + さえ / でさえ; Verb ます-stem + さえ + する","note":"Gives an extreme example to imply everything else; でさえ is used with a subject.","examples":[{"ja":"忙しくて、食事をする時間さえない。","en":"I'm so busy I don't even have time to eat."},{"ja":"そんなことは子供でさえ知っている。","en":"Even a child knows something like that."},{"ja":"彼は{挨拶|あいさつ}さえしなかった。","en":"He didn't even say hello."}],"id":"n3g111"},{"pattern":"〜さえ〜ば","meaning":"if only ~; as long as ~","formation":"Noun + さえ + Verb ば-form; Verb ます-stem + さえすれば; Verb て-form + さえいれば","note":"Only this one condition is needed for the result.","examples":[{"ja":"お金さえあれば、何でも買える。","en":"As long as you have money, you can buy anything."},{"ja":"この薬を飲みさえすれば、すぐ治ります。","en":"If you just take this medicine, you'll get better soon."},{"ja":"君がそばにいてくれさえすれば、それでいい。","en":"As long as you're by my side, that's enough."}],"id":"n3g112"},{"pattern":"〜まで (even)","meaning":"even ~ (going as far as including something unexpected)","formation":"Noun + まで (+ particle: にまで, とまで)","note":"Adds an extreme item on top of others; often with だけでなく or 〜も.","examples":[{"ja":"親友にまで{嘘|うそ}をつかれた。","en":"I was lied to even by my best friend."},{"ja":"子供だけでなく、大人までこのゲームに夢中だ。","en":"Not just children but even adults are hooked on this game."},{"ja":"風が強い上に、{雷|かみなり}まで鳴り出した。","en":"The wind was strong, and then even thunder started."}],"id":"n3g113"},{"pattern":"〜ずに","meaning":"without ~ing (written form of 〜ないで)","formation":"Verb ない-stem + ずに (する → せずに)","note":"More formal than 〜ないで. Remember the irregular form せずに.","examples":[{"ja":"朝ご飯を食べずに学校へ行った。","en":"I went to school without eating breakfast."},{"ja":"辞書を使わずに、この{文章|ぶんしょう}を読んでください。","en":"Please read this passage without using a dictionary."},{"ja":"彼は何も言わずに帰ってしまった。","en":"He went home without saying anything."}],"id":"n3g114"},{"pattern":"〜ないで済む / 〜ずに済む","meaning":"to get by without ~; to not have to ~ (after all)","formation":"Verb ない-form + で済む; Verb ない-stem + ずに済む; Noun + で済む","note":"Expresses relief at avoiding something. Noun + で済む = 'only ~ was needed'.","examples":[{"ja":"友達が車で送ってくれたので、タクシーに乗らずに済んだ。","en":"A friend drove me, so I didn't have to take a taxi."},{"ja":"近くの店で買えたので、遠くまで行かないで済んだ。","en":"I could buy it at a nearby shop, so I didn't have to go far."},{"ja":"軽いけがで済んでよかった。","en":"I'm glad it was only a minor injury."}],"id":"n3g115"},{"pattern":"〜ふうに","meaning":"in a ~ way; like ~","formation":"こんな / そんな / あんな / どんな + ふうに; Plain form + ふうに; Noun + の + ふうに","note":"Describes a manner or style; often interchangeable with ように in speech.","examples":[{"ja":"こんなふうに書いてください。","en":"Please write it like this."},{"ja":"どんなふうに作ったのか教えてください。","en":"Please tell me how you made it."},{"ja":"{将来|しょうらい}はどんなふうに生きたいですか。","en":"How do you want to live in the future?"}],"id":"n3g116"},{"pattern":"〜としたら / 〜とすれば","meaning":"if (we suppose) ~; assuming ~","formation":"Plain form + としたら / とすれば / とすると","note":"Introduces a hypothesis and its consequence; often with もし or 仮に.","examples":[{"ja":"もし{宝|たから}くじが当たったとしたら、何をしますか。","en":"If you won the lottery, what would you do?"},{"ja":"一時間に十ページ読むとすれば、全部で五時間かかる。","en":"If you read ten pages an hour, it will take five hours in total."},{"ja":"彼が来ないとすると、{誰|だれ}が代わりに行くのだろう。","en":"Assuming he doesn't come, who will go in his place?"}],"id":"n3g117"},{"pattern":"〜たら〜た (discovery)","meaning":"when I did ~, (I found that) ~","formation":"Verb た-form + ら + past-tense result","note":"The result is something discovered or unexpected, not an action the speaker controlled.","examples":[{"ja":"家に帰ったら、{荷物|にもつ}が{届|とど}いていた。","en":"When I got home, I found a package had arrived."},{"ja":"窓を開けたら、外は雪だった。","en":"When I opened the window, it was snowing outside."},{"ja":"{久|ひさ}しぶりに会ったら、彼はとても{痩|や}せていた。","en":"When I saw him for the first time in a while, he had gotten very thin."}],"id":"n3g118"},{"pattern":"〜がする","meaning":"there's a (smell / sound / taste / feeling) of ~","formation":"Noun (におい・音・味・声・感じ) + がする","note":"Describes what your senses pick up: いいにおいがする, 変な音がする, 甘い味がする. 〜気がする (to have a feeling that ~) is a separate point.","examples":[{"ja":"台所からいいにおいがする。","en":"There's a lovely smell coming from the kitchen."},{"ja":"夜中に変な音がして、目が覚めた。","en":"I heard a strange noise in the night and woke up."}],"id":"n3g119"},{"pattern":"〜合う","meaning":"to do ~ together; to do ~ to each other","formation":"Verb ます-stem + 合う","note":"Makes an action mutual: 話し合う, 助け合う, 知り合う.","examples":[{"ja":"困ったときは、助け合うことが大切だ。","en":"When times are hard, it's important to help one another."},{"ja":"二人は手紙で{連絡|れんらく}し合っている。","en":"The two of them keep in touch by letter."},{"ja":"この問題について、みんなで話し合いましょう。","en":"Let's all discuss this problem together."}],"id":"n3g120"},{"pattern":"〜直す","meaning":"to redo ~; to do ~ again (to fix or improve it)","formation":"Verb ます-stem + 直す","note":"Doing an action over again, usually because the first attempt was wrong or not good enough.","examples":[{"ja":"間違えたので、手紙を書き直した。","en":"I made a mistake, so I rewrote the letter."},{"ja":"もう一度考え直してみます。","en":"I'll reconsider it once more."},{"ja":"よく聞こえなかったので、電話をかけ直した。","en":"I couldn't hear well, so I called back."}],"id":"n3g121"},{"pattern":"決して〜ない","meaning":"never ~; by no means ~","formation":"決して + negative form","note":"Strong denial or resolution; always paired with a negative ending.","examples":[{"ja":"このご{恩|おん}は決して忘れません。","en":"I will never forget this kindness."},{"ja":"決してあきらめないでください。","en":"Please never give up."},{"ja":"この問題は決して{簡単|かんたん}ではない。","en":"This problem is by no means easy."}],"id":"n3g122"},{"pattern":"別に〜ない","meaning":"not particularly ~","formation":"別に + negative form","note":"Downplays something; 別に alone as a reply can sound cold or dismissive.","examples":[{"ja":"別に何も欲しくない。","en":"I don't particularly want anything."},{"ja":"A：怒っているの？B：別に怒っていないよ。","en":"A: Are you angry? B: No, not really."},{"ja":"別に急がなくてもいいですよ。","en":"There's no particular need to hurry."}],"id":"n3g123"},{"pattern":"〜てはじめて","meaning":"only after ~ (did I realize / could I ~)","formation":"Verb て-form + はじめて (also written て初めて)","note":"Something is realized or achieved only after an experience; often with わかる / 気づく.","examples":[{"ja":"病気になってはじめて、健康の大切さがわかった。","en":"Only after getting sick did I realize how important health is."},{"ja":"親になってはじめて、親の気持ちがわかった。","en":"It wasn't until I became a parent that I understood my parents' feelings."},{"ja":"一人で暮らしてはじめて、母の苦労に気づいた。","en":"Only after living alone did I notice how hard my mother worked."}],"id":"n3g124"},{"pattern":"〜とのことだ","meaning":"I was told that ~; they say ~ (formal hearsay, often relaying a message)","formation":"Plain form + とのことだ / とのことです","note":"Common when passing on a message from someone; more formal than そうだ.","examples":[{"ja":"田中さんから電話があって、少し遅れるとのことです。","en":"Mr. Tanaka called and said he'll be a little late."},{"ja":"先生によると、明日の{授業|じゅぎょう}は休みとのことだ。","en":"According to the teacher, tomorrow's class is canceled."},{"ja":"部長は午後三時に戻られるとのことです。","en":"I'm told the manager will be back at 3 p.m."}],"id":"n3g125"}];